// ── Bubble Sort with early-exit optimisation ──────────────────
function bubbleSort(arr) {
  const a = [...arr]; // non-destructive copy
  for (let i = 0; i < a.length - 1; i++) {
    let swapped = false;
    for (let j = 0; j < a.length - 1 - i; j++) {
      if (a[j] > a[j + 1]) {
        [a[j], a[j + 1]] = [a[j + 1], a[j]];
        swapped = true;
      }
    }
    if (!swapped) break; // already sorted — O(n) best case
  }
  return a;
}

// ── Insertion Sort — adaptive, stable, in-place ───────────────
function insertionSort(arr) {
  const a = [...arr];
  for (let i = 1; i < a.length; i++) {
    const key = a[i];
    let j = i - 1;
    // Shift elements larger than key one position right
    while (j >= 0 && a[j] > key) {
      a[j + 1] = a[j];
      j--;
    }
    a[j + 1] = key; // insert key in its correct position
  }
  return a;
}

// ── Selection Sort — minimal swaps ───────────────────────────
function selectionSort(arr) {
  const a = [...arr];
  for (let i = 0; i < a.length - 1; i++) {
    let minIdx = i;
    for (let j = i + 1; j < a.length; j++) {
      if (a[j] < a[minIdx]) minIdx = j;
    }
    if (minIdx !== i) [a[i], a[minIdx]] = [a[minIdx], a[i]];
  }
  return a;
}

const arr = [38, 27, 43, 3, 9, 82, 10];
console.log(bubbleSort(arr));    // [3, 9, 10, 27, 38, 43, 82]
console.log(insertionSort(arr)); // [3, 9, 10, 27, 38, 43, 82]
console.log(selectionSort(arr)); // [3, 9, 10, 27, 38, 43, 82]

// Insertion sort shines on nearly-sorted data:
const nearSorted = [1, 2, 4, 3, 5, 6, 7]; // only 1 inversion
console.log(insertionSort(nearSorted)); // O(n+1) = effectively O(n)

// ── Merge Sort — O(n log n) stable, O(n) space ──────────────
function mergeSort(arr) {
  if (arr.length <= 1) return arr;          // base case
  const mid = Math.floor(arr.length / 2);
  const left  = mergeSort(arr.slice(0, mid)); // recurse left
  const right = mergeSort(arr.slice(mid));    // recurse right
  return merge(left, right);
}

function merge(left, right) {
  const result = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    // '<=' is the stability guarantee:
    // equal elements from the left sub-array come first
    if (left[i] <= right[j]) {
      result.push(left[i++]);
    } else {
      result.push(right[j++]);
    }
  }
  // Append remaining elements (one of these slices will be empty)
  return result.concat(left.slice(i)).concat(right.slice(j));
}

// ── Stability demonstration ──────────────────────────────────
const tasks = [
  { name: 'compile',  priority: 2 },
  { name: 'lint',     priority: 1 },
  { name: 'test',     priority: 2 },  // same priority as 'compile'
  { name: 'deploy',   priority: 3 },
];
// Sort by priority — stable sort preserves 'compile' before 'test'
const sorted = mergeSort(tasks.map((t, i) => ({ ...t, originalIdx: i })));
// With a comparator-capable merge sort, equal priorities keep original order

const nums = [38, 27, 43, 3, 9, 82, 10];
console.log(mergeSort(nums)); // [3, 9, 10, 27, 38, 43, 82]

// ── Counting merge sort call depth for intuition ─────────────
// n=8  → 3 levels (log₂ 8 = 3)
// n=16 → 4 levels
// n=1M → ~20 levels  (log₂ 1,048,576 ≈ 20)
// At 1M elements, merge sort does ~20M comparisons.
// Bubble sort would do 500 BILLION — a 25,000x difference.

// ── Quicksort with random pivot (Lomuto partition) ──────────
function quickSort(arr, lo = 0, hi = arr.length - 1) {
  if (lo >= hi) return; // base case: 0 or 1 elements

  // Tail recursion on smaller partition bounds stack to O(log n)
  const pivotIdx = partition(arr, lo, hi);
  if (pivotIdx - lo < hi - pivotIdx) {
    quickSort(arr, lo, pivotIdx - 1);  // recurse on smaller
    quickSort(arr, pivotIdx + 1, hi); // recurse on larger (tail)
  } else {
    quickSort(arr, pivotIdx + 1, hi); // recurse on smaller
    quickSort(arr, lo, pivotIdx - 1); // recurse on larger (tail)
  }
}

function partition(arr, lo, hi) {
  // Random pivot: swap with hi so Lomuto works cleanly
  const pivotIdx = lo + Math.floor(Math.random() * (hi - lo + 1));
  [arr[pivotIdx], arr[hi]] = [arr[hi], arr[pivotIdx]];
  const pivot = arr[hi];

  let i = lo - 1; // boundary of the "small" region
  for (let j = lo; j < hi; j++) {
    if (arr[j] <= pivot) {
      i++;
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
  }
  // Place pivot in its final sorted position
  [arr[i + 1], arr[hi]] = [arr[hi], arr[i + 1]];
  return i + 1; // pivot's final index
}

// In-place: modifies the original array
const data = [38, 27, 43, 3, 9, 82, 10];
quickSort(data);
console.log(data); // [3, 9, 10, 27, 38, 43, 82]

// ── Why quicksort is NOT stable ─────────────────────────────
// During partition, a swap may move an element past an equal one
// Example: [{v:3,id:1}, {v:3,id:2}] — after partition, id:2 may
// appear before id:1. For stable sort, use mergeSort or Array.sort.

// ── Complexity & Stability Reference ────────────────────────
//
// Algorithm      | Best     | Average  | Worst    | Space    | Stable
// ---------------|----------|----------|----------|----------|-------
// Bubble Sort    | O(n)     | O(n²)    | O(n²)    | O(1)     | Yes
// Selection Sort | O(n²)    | O(n²)    | O(n²)    | O(1)     | No
// Insertion Sort | O(n)     | O(n²)    | O(n²)    | O(1)     | Yes
// Merge Sort     | O(n lgn) | O(n lgn) | O(n lgn) | O(n)     | Yes
// Quicksort      | O(n lgn) | O(n lgn) | O(n²)    | O(log n) | No
// TimSort        | O(n)     | O(n lgn) | O(n lgn) | O(n)     | Yes

// ── Stability: why it matters ────────────────────────────────
const employees = [
  { name: 'Alice',  dept: 'Eng',  salary: 90000 },
  { name: 'Bob',    dept: 'Eng',  salary: 85000 },
  { name: 'Carol',  dept: 'Sales', salary: 92000 },
  { name: 'Dave',   dept: 'Sales', salary: 85000 },
];
// Goal: sort by dept, then by salary within dept
// Step 1: stable sort by salary
employees.sort((a, b) => a.salary - b.salary);
// => Bob(85k), Dave(85k), Alice(90k), Carol(92k)  [salary order]
// Step 2: stable sort by dept
employees.sort((a, b) => a.dept.localeCompare(b.dept));
// => Alice(90k), Bob(85k) [Eng], Carol(92k), Dave(85k) [Sales]
// Within Eng: Alice before Bob (salary order preserved from step 1)
// Within Sales: Carol before Dave (salary order preserved from step 1)
// This TWO-PASS TECHNIQUE only works with a STABLE sort.

// ── When to reach for each algorithm ────────────────────────
// n < 20              → insertion sort (or just Array.sort, it does this internally)
// stability required  → Array.sort (TimSort) or mergeSort
// in-place, no stable → quickSort with random pivot
// guaranteed O(n lgn) → merge sort or Array.sort
// writes are costly   → selection sort (exactly n-1 writes)
// nearly-sorted data  → insertion sort or TimSort
